sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// 1. Validação de Campos Obrigatórios(Usando forEach com verificação segura)
	var mandatoryFields = [
		'u_nome_solicitante',
		'u_cpf_solicitante',
		'u_data_nascimento_solicitante',
		'u_email_solicitante',
		'u_telefone_solicitante',
		'description'
	];

	var emptyField = "";

	mandatoryFields.forEach(function (field) {
		var val = current[field];
		if (!emptyField && (!val || String(val).trim() === "")) {
			emptyField = field;
		}
	});

	if (emptyField) {
		current.setAbortAction(true);
		gs.info("VALIDACAO - Erro: O campo '" + emptyField + "' é obrigatório.");
		return;
	}

	var grEv = new GlideRecord('x_fub_fundbrad_ev_atendimento_ev');
	grEv.addQuery('u_protocolo_origem', current.u_protocolo_origem);
	grEv.query();

	if (grEv.next()) {
		current.setAbortAction(true);
		gs.info("DUPLICADO - Erro: Protocolo de origem já associado ao case: " + grEv.number);
		return;
	}

	var validator = new x_fub_fundbrad_ev.EVUtils;

	var nomeResult = validator.validateName(current.u_nome_solicitante);

	if (nomeResult !== 'true') {
		current.setAbortAction(true);
		gs.info("VALIDACAO - Erro de validação: O nome do solicitante contém caracteres inválidos.");
	}

	if (validator.validarCPF(current.u_cpf_solicitante) !== 'true') {
		current.setAbortAction(true);
		gs.info("VALIDACAO - Erro de validação: O CPF informado(" + current.u_cpf_solicitante + ") é inválido.");

	}

	if (validator.isDateGreaterThanToday(current.u_data_nascimento_solicitante) === 'true') {
		current.setAbortAction(true);
		gs.info("VALIDACAO - Erro de validação: A data de nascimento não pode ser uma data futura.");
	}

	var phoneResult = JSON.parse(validator.formatPhoneNumber(current.u_telefone_solicitante));
	if (!phoneResult.isValid) {
		current.setAbortAction(true);
		gs.info("Erro de validação: O número de telefone informado é inválido. Formatos aceitos: 10 ou 11 dígitos(com DDD).");
	}

	if (!validator.isEmailValid(current.u_email_solicitante)) {
		current.setAbortAction(true);
		gs.info("Erro de validação: O e-mail informado(" + current.u_email_solicitante + ") possui um formato inválido.");
	}


})(current, previous);
